package store.cadera.cdrjobs.placeholder;
import me.clip.placeholderapi.expansion.PlaceholderExpansion;import org.bukkit.OfflinePlayer;import org.jetbrains.annotations.*;import store.cadera.cdrjobs.CdrJobsPlugin;import store.cadera.cdrjobs.data.*;import store.cadera.cdrjobs.model.*;import store.cadera.cdrjobs.service.*;import store.cadera.cdrjobs.util.JobRanks;
public final class CdrJobsExpansion extends PlaceholderExpansion{private final CdrJobsPlugin plugin;private final Database db;private final ProfessionStore store;private final LevelService levels;public CdrJobsExpansion(CdrJobsPlugin p,Database d,ProfessionStore s,LevelService l){plugin=p;db=d;store=s;levels=l;}@Override public @NotNull String getIdentifier(){return"cdrjobs";}@Override public @NotNull String getAuthor(){return"CADERA";}@Override public @NotNull String getVersion(){return plugin.getPluginMeta().getVersion();}@Override public boolean persist(){return true;}@Override public @Nullable String onRequest(OfflinePlayer p,@NotNull String param){if(p==null||p.getUniqueId()==null)return"";String q=param.toLowerCase();if(q.equals("fate_essence"))return String.valueOf(db.getFateEssence(p.getUniqueId()));for(JobType j:JobType.values()){String prefix=j.name().toLowerCase()+"_";if(q.startsWith(prefix)){JobProgress pr=db.getProgress(p.getUniqueId(),j);String tail=q.substring(prefix.length());return switch(tail){case"level"->String.valueOf(pr.level());case"xp"->String.valueOf(pr.xp());case"xp_required"->String.valueOf(levels.xpRequiredForNextLevel(pr.level()));case"rank"->JobRanks.title(j,pr.level());default->metric(p,j,tail);};}}MinerTrialProgress t=db.getMinerTrialProgress(p.getUniqueId());return switch(q){case"miner_trial_stone"->t.stoneComplete()?"COMPLETED":"IN PROGRESS";case"miner_trial_deep"->t.deepComplete()?"COMPLETED":"IN PROGRESS";case"miner_total_ores"->String.valueOf(t.totalOres());default->null;};}private String metric(OfflinePlayer p,JobType j,String tail){String job=j.name();String metric=switch(j){case FARMER->tail.equals("harvests")?"harvests":null;case HUNTER->tail.equals("kills")?"kills":null;case LUMBERJACK->tail.equals("logs")?"logs":null;case FISHER->tail.equals("catches")?"catches":null;default->null;};return metric==null?null:String.valueOf(store.getCounter(p.getUniqueId(),job,metric));}}
